package com.securedeploy.auth.security;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.*;import org.springframework.dao.DataAccessResourceFailureException;import com.securedeploy.persistence.repository.UserRepository;import com.securedeploy.persistence.entity.UserEntity;import org.springframework.security.core.context.SecurityContextHolder;
class AuthStoreOutageTest {
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void databaseOutageIs503AndRecoveryAcceptsSameValidToken()throws Exception {
  var jwt=mock(JwtTokenProvider.class);var users=mock(UserRepository.class);when(jwt.extractUserId("synthetic-token")).thenReturn(1L);when(users.findById(1L)).thenThrow(new DataAccessResourceFailureException("synthetic-private-database-detail"));var filter=new JwtAuthenticationFilter(jwt,users);var request=new MockHttpServletRequest("GET","/api/projects");request.addHeader("Authorization","Bearer synthetic-token");var response=new MockHttpServletResponse();var chain=new MockFilterChain();filter.doFilter(request,response,chain);assertEquals(503,response.getStatus());assertTrue(response.getContentAsString().contains("AUTH_STORE_UNAVAILABLE"));assertFalse(response.getContentAsString().contains("synthetic-private"));assertNull(chain.getRequest());assertNull(SecurityContextHolder.getContext().getAuthentication());
  var user=mock(UserEntity.class);when(user.getId()).thenReturn(1L);when(user.getEmail()).thenReturn("control@example.invalid");when(user.getName()).thenReturn("CONTROL");reset(users);when(users.findById(1L)).thenReturn(java.util.Optional.of(user));var recovered=new MockHttpServletRequest("GET","/api/projects");recovered.addHeader("Authorization","Bearer synthetic-token");var after=new MockFilterChain();filter.doFilter(recovered,new MockHttpServletResponse(),after);assertNotNull(after.getRequest());assertEquals(1L,((AuthenticatedUser)SecurityContextHolder.getContext().getAuthentication().getPrincipal()).id());
 }
}
